  "codebook": {
    "definition": "Credit-claiming is defined as a senator's public claim of direct or shared responsibility for a specific, positive, and concrete government outcome (e.g., securing federal funding, grants, projects, passed legislation, or resolved casework) that benefits their home state, local constituents, or a targeted group.",
    "clarification": "To classify a press release as credit-claiming (1), look for language where the senator actively connects their legislative work, committee role, or advocacy to a finalized positive benefit. Key indicators include phrases like 'I secured,' 'I fought to obtain,' 'the funding I requested,' or announcing federal grants allocated to their state. Simply announcing home-state grants is considered credit-claiming as it associates the senator with the delivered federal resources.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "Senators Baucus and Tester explicitly claim that they 'delivered on their promise to secure federal funding' and 'went to bat' for $12.5 million in military projects for Butte, Montana."
      },
      {
        "document_id": "2697",
        "explanation": "Senator Inouye takes direct credit for securing $225,000 to combat coqui frogs in Hawaii, detailing how he personally intervened and found an alternative funding source after the administration rejected his initial request."
      },
      {
        "document_id": "1257",
        "explanation": "Senator DeWine announces a local firefighter grant and takes credit for the outcome by highlighting that he wrote and passed the underlying 'FIRE Act' that enabled the funding."
      }
    ],
    "negative_clarification": "Do NOT classify a text as credit-claiming (0) if the senator is merely introducing or co-sponsoring a bill that has not passed, expressing an opinion (position-taking), calling on agencies to act without a completed outcome (advocacy), conducting committee oversight, issuing condolences, or distributing personal/office-created awards. If a senator announces federal funding but explicitly attributes the success of securing it entirely to local entities or other actors rather than themselves, it is also classified as 0.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "Senator Kennedy introduces a bill to enhance stem cell research. Sponsoring or introducing a bill that has not yet passed is position-taking, as no concrete policy outcome has been finalized or delivered."
      },
      {
